import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`ad-builder`,heroTitle:`Generate on-brand ads at scale`,heroSubtitle:`Perplexity Computer studies your website, learns your brand voice and design, and builds you a custom app to generate high-quality ads — automatically.`,heroCta:`Get Started`,inputUrlCta:`Build my ad engine`,inputUrlPrefill:`Go to {url} and do a deep brand analysis — extract the brand voice, tone, visual style, color palette, typography, logo usage, messaging pillars, and target audience. Then build me a custom web app deployed to a live URL that lets me generate on-brand ad creatives at scale. The app should support multiple formats: social ads (Facebook, Instagram, LinkedIn, TikTok), display banners (standard IAB sizes), and search ad copy (Google Ads RSAs). For each format, I should be able to enter a product name, promo details, or campaign brief and instantly get multiple variations with headlines, body copy, CTAs, and visual direction — all matching my brand guidelines. Include a brand style preview panel so I can verify consistency. Save my brand profile so future sessions start with my guidelines already loaded.`,heroOverlaySteps:[`Studying your website for brand voice, design, and messaging`,`Building a custom app to generate on-brand ad creatives`,`Supporting social, display, and search ad formats`,`Your ad engine deployed to a live URL, ready to use`],generatingSteps:[`Visiting {url} to extract brand voice, colors, typography, and messaging`,`Designing an app that generates ad creatives matching your brand guidelines`,`Configuring templates for social, display, and search ad formats`,`Deploying your custom ad engine to a live URL`],featureSectionTitle:`Your brand. Infinite ads.`,featureCardTitles:[`Connects to your tools`,`Ads ready to run`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Slack, Google Drive — Computer pipes your ad creatives and copy straight into the tools you already use.`,`Headlines. Body copy. Design direction. Computer generates on-brand ad variations you can review and launch across any channel.`],capabilitySectionTitle:`Your creative team, at scale`,capabilitySectionSubtitle:`Enter your URL, get back a custom ad generation engine.`,capabilityCards:[{title:`Brand Analysis`,description:`Computer studies your website — voice, tone, colors, typography, and messaging — to build a complete brand profile.`},{title:`Custom Ad App`,description:`Computer builds and deploys a web app tailored to your brand — pick a format, enter a product, and generate ad variations instantly.`},{title:`Multi-Format Support`,description:`Social ads, display banners, search copy — your app generates on-brand creatives for every channel from a single prompt.`},{title:`Dozens of Variations`,description:`Computer generates multiple ad variations per prompt — different headlines, angles, and CTAs, all matching your brand.`},{title:`Learns Your Brand`,description:`Computer remembers your brand guidelines, past creatives, and top performers — so every ad gets better over time.`},{title:`Always Up to Date`,description:`Computer monitors your website for brand updates — and keeps your ad engine in sync with your latest messaging.`}]});export{t as default};
